        this._sectionContents[section.id] = content;
        const toggle = document.createElement('div');
        toggle.className = 'mp_plainBtn mp_fl_toggle';
        toggle.role = 'button';
        toggle.style.display = 'inline-block';
        toggle.style.marginLeft = '8px';
